<?php
declare(strict_types=1); namespace App\Controller; use App\Entity\Application; use App\Entity\Candidate; use App\Entity\Company; use App\Entity\Job; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Security\Http\Attribute\IsGranted;
#[Route('/admin'),IsGranted('ROLE_ADMIN')] final class AdminController extends AbstractController { #[Route('',name:'admin_dashboard')] public function index(EntityManagerInterface $em):Response{return $this->render('admin/index.html.twig',['counts'=>['candidates'=>$em->getRepository(Candidate::class)->count([]),'companies'=>$em->getRepository(Company::class)->count([]),'jobs'=>$em->getRepository(Job::class)->count([]),'applications'=>$em->getRepository(Application::class)->count([])]]);} }
